import re


def normalize_path(path):
    """Replace all valid {variable_name} patterns with {var}"""
    return re.sub(r'\{[a-zA-Z0-9_-]+\}', '{var}', path)


def is_valid_method(method):
    return method.upper() in {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}


def is_valid_permission(perm):
    return perm.upper() in {'ALLOW', 'DENY'}


def is_parent_prefix(normalized_parent, normalized_child):
    """Check if normalized_parent is a proper path prefix of normalized_child"""
    if normalized_parent == normalized_child:
        return False
    if not normalized_child.startswith(normalized_parent):
        return False
    # Check that the prefix ends at a segment boundary
    rest = normalized_child[len(normalized_parent):]
    return rest.startswith('/')


def main():
    with open('/app/input.txt') as f:
        content = f.read()

    # Split into sections by empty lines
    lines = content.splitlines()
    sections = []
    current = []
    for line in lines:
        if line.strip() == '':
            if current:
                sections.append(current)
                current = []
        else:
            current.append(line)
    if current:
        sections.append(current)

    endpoints_lines = sections[0] if len(sections) > 0 else []
    base_exclude_lines = sections[1] if len(sections) > 1 else []
    plan_lines = sections[2] if len(sections) > 2 else []

    # Parse ENDPOINTS with hard cutoff
    endpoints = []
    for line in endpoints_lines:
        fields = line.split()
        if len(fields) != 4:
            break
        path, method, role, perm = fields
        if not path:
            break
        if not is_valid_method(method):
            break
        if not role:
            break
        if not is_valid_permission(perm):
            break
        endpoints.append((path, method.upper(), role, perm.upper()))

    # Parse BASE/EXCLUDE
    base_path = None
    excluded_roles = set()
    for line in base_exclude_lines:
        fields = line.split()
        if len(fields) >= 2 and fields[0] == 'base':
            base_path = fields[1]
        elif len(fields) >= 1 and fields[0] == 'exclude':
            excluded_roles = set(fields[1:])

    # Parse PLAN with hard cutoff
    plan = []
    for line in plan_lines:
        fields = line.split()
        if len(fields) != 2:
            break
        path, method = fields
        if not path:
            break
        if not is_valid_method(method):
            break
        plan.append((path, method.upper()))

    # Deduplicate by (normalized_path, method, role), keeping first encountered
    seen = set()
    deduped = []
    for ep in endpoints:
        key = (normalize_path(ep[0]), ep[1], ep[2])
        if key not in seen:
            seen.add(key)
            deduped.append(ep)
    endpoints = deduped

    # Filter by base path prefix
    if base_path:
        endpoints = [ep for ep in endpoints if ep[0].startswith(base_path)]

    if not plan:
        # Empty PLAN: include all eligible after base filter, excluded roles filtered out (no inheritance exception)
        if excluded_roles:
            endpoints = [ep for ep in endpoints if ep[2] not in excluded_roles]
        result = endpoints
    else:
        # Non-empty PLAN
        plan_norms = [(normalize_path(p), m) for p, m in plan]

        # Find which PLAN entries match endpoints
        matching_plan_indices = set()
        matching_paths = set()
        for i, (pnorm, pm) in enumerate(plan_norms):
            for ep in endpoints:
                ep_norm = normalize_path(ep[0])
                if ep_norm == pnorm and ep[1] == pm:
                    matching_plan_indices.add(i)
                    matching_paths.add(ep_norm)
                    break

        # Find parent paths for matching PLAN entries only
        parent_paths = set()
        for i, (pnorm, pm) in enumerate(plan_norms):
            if i not in matching_plan_indices:
                continue
            for ep in endpoints:
                ep_norm = normalize_path(ep[0])
                if ep_norm != pnorm and is_parent_prefix(ep_norm, pnorm):
                    parent_paths.add(ep_norm)

        needed_paths = matching_paths | parent_paths

        # Apply excluded roles filter with inheritance exception
        if excluded_roles:
            filtered = []
            for ep in endpoints:
                ep_norm = normalize_path(ep[0])
                if ep[2] in excluded_roles:
                    # Inheritance exception: include if this is a needed parent path
                    # and all endpoints for this path are for excluded roles
                    if ep_norm in parent_paths:
                        all_excluded = all(
                            other[2] in excluded_roles
                            for other in endpoints
                            if normalize_path(other[0]) == ep_norm
                        )
                        if all_excluded:
                            filtered.append(ep)
                else:
                    filtered.append(ep)
            endpoints = filtered

        # Filter to only needed paths
        endpoints = [ep for ep in endpoints if normalize_path(ep[0]) in needed_paths]
        result = endpoints

    # Sort by path specificity, method, role, permission
    def sort_key(ep):
        path, method, role, perm = ep
        segments = len([s for s in path.split('/') if s])
        perm_order = 0 if perm == 'ALLOW' else 1
        return (-segments, method, role, perm_order)

    result.sort(key=sort_key)

    # Output
    with open('/app/output.txt', 'w') as f:
        if not result:
            f.write('\n')
        else:
            for path, method, role, perm in result:
                f.write(f'{path} {method} {role} {perm}\n')


if __name__ == '__main__':
    main()
